"""Use real generic methods with fresh equal-valued string query keys."""
CORE=r'''
@SuppressWarnings("unchecked") static <K> K hashKeyCopy7(K key){return key instanceof String text?(K)new String(text):key;}
static void hashCheck7(boolean ok,String message){if(!ok)throw new IllegalStateException(message);}
static JsonValue hashEncode7(Object value,boolean numbers){if(numbers){hashCheck7(value instanceof Integer,"Preserve integer generic values");return Json.value((Integer)value);}hashCheck7(value instanceof String,"Preserve string generic values");return Json.value((String)value);}
static <K,V> JsonValue hashRun7(JsonObject row,ArrayList<K> keys,ArrayList<V> values,boolean valueNumbers){var args=row.get("arguments").asArray();int capacity=args.get(1).asInt();var actor=new HashTable<K,V>(capacity);var other=new HashTable<K,V>(capacity);other.Put(hashKeyCopy7(keys.get(0)),values.get(0));hashCheck7(!actor.Contains(hashKeyCopy7(keys.get(0))),"New table instances own independent empty state");try{hashCheck7(HashTable.class.getMethod("Put",Object.class,Object.class).getReturnType()==void.class&&HashTable.class.getMethod("Remove",Object.class).getReturnType()==boolean.class&&HashTable.class.getMethod("Contains",Object.class).getReturnType()==boolean.class,"Use the declared generic void/boolean methods");}catch(NoSuchMethodException error){throw new IllegalStateException("Use the declared generic API",error);}var results=new JsonArray().add(Json.NULL);var seen=new ArrayList<K>();var operations=args.get(2).asArray();for(int i=1;i<operations.size();++i){K key=keys.get(i);if(!seen.contains(key))seen.add(key);K supplied=hashKeyCopy7(key);String operation=operations.get(i).asString();JsonValue result;switch(operation){case "Put":actor.Put(supplied,values.get(i));result=Json.NULL;break;case "Get":try{V value=actor.Get(supplied);result=hashEncode7(value,valueNumbers);}catch(NoSuchElementException error){result=new JsonObject().add("error","missing");}break;case "Remove":boolean removed=actor.Remove(supplied);result=Json.value(removed);break;case "Contains":boolean present=actor.Contains(supplied);result=Json.value(present);break;default:throw new IllegalStateException("Unknown operation");}results.add(result);}var entries=new JsonArray();for(K key:seen){try{V value=actor.Get(hashKeyCopy7(key));entries.add(new JsonArray().add(hashEncode7(key,!valueNumbers)).add(hashEncode7(value,valueNumbers)));}catch(NoSuchElementException error){}}return new JsonObject().add("actual",new JsonObject().add("results",results).add("finalEntries",entries)).add("mutationOk",true);}
static JsonValue executeHash7(JsonObject row){var args=row.get("arguments").asArray();if(args.get(0).asString().equals("text-number")){var keys=new ArrayList<String>();var values=new ArrayList<Integer>();for(var key:args.get(3).asArray())keys.add(new String(key.asString()));for(var value:args.get(4).asArray())values.add(value.asInt());return hashRun7(row,keys,values,true);}var keys=new ArrayList<Integer>();var values=new ArrayList<String>();for(var key:args.get(3).asArray())keys.add(key.asInt());for(var value:args.get(4).asArray())values.add(value.asString());return hashRun7(row,keys,values,false);}
'''
